// lib/edge/src/count.rs:19-43
let points_count = if exact {
    segments.map(|segment| segment.get().read().read_filtered(...))
        .process_results(|iter| iter.flatten().count())?   // 精确路径: 谓词过滤
} else {
    let cardinality = segments.map(|segment| segment.get().read()
        .estimate_point_count(filter.as_ref(), ...))
        .process_results(|iter| iter.merge_independent())?;
    cardinality.exp                                          // 近似路径: 直接取估计期望值
};

// lib/segment/src/index/field_index/geo_index/mod.rs:36,588-613
const GEO_QUERY_MAX_REGION: usize = 12;
fn estimate_cardinality(...) {
    if let Some(geo_bounding_box) = &condition.geo_bounding_box {
        let Some(geo_hashes) = rectangle_hashes(geo_bounding_box, GEO_QUERY_MAX_REGION).ok() else { return Ok(None); };
        let mut estimation = self.match_cardinality(&geo_hashes, hw_counter)?; ...
    }
    if let Some(geo_radius) = &condition.geo_radius {
        let Some(geo_hashes) = circle_hashes(geo_radius, GEO_QUERY_MAX_REGION).ok() else { ... };
        let mut estimation = self.match_cardinality(&geo_hashes, hw_counter)?; ...
    }
}

// lib/segment/src/index/field_index/geo_hash.rs:309-340 geohash_regions: 从 bbox 角点 truncate(precision) 起, 沿东/南 sphere_neighbor 逐格枚举, seen.len() > max_regions 即返回 None → 降精度重试; create_hashes 取满足 max_regions 的最高精度覆盖。

// lib/segment/src/types.rs:2880-2891 exact 路径谓词 GeoBoundingBox::check_point: top_left.lon > bottom_right.lon 时走 antimeridian 分支 (point.lon > top_left.lon || point.lon < bottom_right.lon)。
